	public static boolean checkLogin()
			throws InterruptedException, EncryptedDocumentException, InvalidFormatException, IOException {
		LoginPage lp = new LoginPage(getDriver());

		lp.checkLoginPageTitleByURLInputInBrowser(DriverUtility.FINUrl);

		Thread.sleep(3000);

		re_LunchBrowser();

		Thread.sleep(5000);

		String unamelt = "su";

		String pawslt = "su";

		lp.enterUserName(unamelt);

		lp.enterPassword(pawslt);

		System.err.println("Login-----------------------------------------");

		String compname = "BillWise";

		Select oSelect = new Select(companyDropDownList);

		List<WebElement> elementCount = oSelect.getOptions();

		int cqSize = elementCount.size();

		System.out.println("CompanyDropdownList Count :" + cqSize);

		int i;

		for (i = 0; i < elementCount.size(); i++) {

			elementCount.get(i).getText();

			String optionName = elementCount.get(i).getText();
			if (optionName.toUpperCase().startsWith(compname.toUpperCase())) {
				System.out.println("q" + elementCount.get(i).getText());
				elementCount.get(i).click();
			}

		}

		Thread.sleep(2000);

		lp.clickOnSignInBtn();

		Thread.sleep(12000);
		
		ReindexPopup();
		
		Thread.sleep(6000);
		getFluentWebDriverWait().until(ExpectedConditions.elementToBeClickable(userNameDisplay));
		String userInfo = userNameDisplay.getText();

		System.out.println("User Info : " + userInfo);

		System.out.println("User Info Capture Text :" + userNameDisplay.getText());

		getFluentWebDriverWait().until(ExpectedConditions.elementToBeClickable(companyLogo));

		companyLogo.click();

		if (userInfo.equalsIgnoreCase("SU")) {

			System.out.println("Test Pass :Logined to Billwise Company");
			return true;

		} else {
			System.out.println("Test Fail :Logined to Billwise Company");
			return false;

		}
	}

