	public static boolean checkVoucherSavingMessage2(String docno)
			throws InterruptedException, EncryptedDocumentException, InvalidFormatException, IOException {

		try {

			if (errorMessage.isDisplayed()) {

				String actErrorMessage = errorMessage2.getText();
				String expErrorMessage = "Voucher saved successfully";
				String expErrorMessage1 = ": " + docno;

				System.out.println("SavingMessage  :  " + actErrorMessage + " Value Expected : " + expErrorMessage + " "
						+ expErrorMessage1);

				if (actErrorMessage.startsWith(expErrorMessage) && actErrorMessage.endsWith(expErrorMessage1)) {

					click(errorMessageCloseBtn);

					return true;

				}
			}

			else if (errorMessage2.isDisplayed()) {

				String actErrorMessage2 = errorMessage.getText();
				String expErrorMessage2 = "Voucher saved successfully";
				String expErrorMessage3 = ": " + docno;

				System.out.println("SavingMessage  :  " + actErrorMessage2 + " Value Expected : " + expErrorMessage2
						+ " " + expErrorMessage3);

				if (actErrorMessage2.startsWith(expErrorMessage2) && actErrorMessage2.endsWith(expErrorMessage3)) {

					click(errorMessageClose2Btn);

					return true;

				}

			}
			return true;

		} catch (Exception e) {
			System.err.println("UNABLE TO COMPARE");
			return false;
		}
	}

