		excludeVoucherRow1.click();
		Thread.sleep(2000);

		enterExcluduVoucher.click();
		removetTxt(enterExcluduVoucher);
		enterExcluduVoucher.sendKeys(Keys.SPACE);

		Thread.sleep(2000);
		int excludeVoucherlistCount = excludeVoucherlist.size();

		ArrayList<String> excludeVoucherlistArray = new ArrayList<String>();

		for (int i = 1; i < excludeVoucherlistCount; i++) {
			String data = excludeVoucherlist.get(i).getText();

			excludeVoucherlistArray.add(data);

		}

		String actexcludeVoucherlist = excludeVoucherlistArray.toString();

		String expexcludeVoucherlist = "[Auto Sales Order, Capitalization of Inventory Stock, Cash Sales, Credit Notes, Credit Notes (Linewise)/Payroll, Credit Notes VAT, Debit Notes, Debit Notes (Linewise), Debit Notes VAT, Delivery Notes, Excesses in Stocks, Fixed Asset Depreciation Voucher, Forex JV, Hire-Purchase Sales, Inter Dep FIFO, Inter-Departmental JV, Issues to Production, Job Order, Job orders, Job Work Issues, Job Work Receipts, Journal Entries, JV FIFO, JV New Reference, JV VAT View, Material Receipt Notes, Material Requisition, Non JV FIFO, NON JV New Reference, Non JV VAT, Non-Standard Journal Entries, Opening BAL FIFO, Opening Bal NewReference, Opening Balances, Opening Balances New, Opening Stocks, Opening Stocks New, Payments, Payments FIFO, Payments VAT, Payroll Postings, PDP FIFO, PDP New Reference, PDP VAT, PDR FIFO, PDR New Reference, PDR VAT, Petty Cash, Petty Cash FIFO]";

		System.out.println("actexcludeVoucherlist   : " + actexcludeVoucherlist);
		System.out.println("expexcludeVoucherlist   : " + expexcludeVoucherlist);

		enterExcluduVoucher.sendKeys(Keys.TAB);

		Thread.sleep(2500);

		click(excludeVoucherRow1);
		removetTxt(enterExcluduVoucher);
		enterExcluduVoucher.sendKeys("Sales Invoices");
		Thread.sleep(2500);

		int count = excludeVoucherlist.size();

		for (int i = 0; i < count; i++) {
			String data = excludeVoucherlist.get(i).getText();

			System.err.println("DATA--------------: " + data);

			if (data.equals("Sales invoice")) {
				excludeVoucherlist.get(i).click();
			}
		}

		Thread.sleep(2000);

		ClickUsingJs(settingUpdateIcon);

		getWaitForAlert();

		getAlert().accept();

		getFluentWebDriverWait().until(ExpectedConditions.elementToBeClickable(errorMessageCloseBtn));
