	public static String checkValidationMessage(String ExpMessage)
			throws InterruptedException, EncryptedDocumentException, InvalidFormatException, IOException {
		try {

			getFluentWebDriverWait().until(ExpectedConditions.elementToBeClickable(errorMessage));
			String actErrorMessage = errorMessage.getText();
			String expErrorMessage = ExpMessage;

			try {
				getFluentWebDriverWait().until(ExpectedConditions.elementToBeClickable(errorMessageCloseBtn));
				errorMessageCloseBtn.click();

				System.out.println("ValidationMessage  Actual:" + actErrorMessage );
				System.out.println("ValidationMessage  Expted:" + expErrorMessage );

				return actErrorMessage;
			} catch (Exception ee) {

				System.out.println("ValidationMessage  :  " + actErrorMessage + " Value Expected : " + expErrorMessage);

				return actErrorMessage;
			}
		} catch (Exception e) {
			System.err.println("Error Message NOT Found or NOT Clickable");
			System.err.println(e.getMessage());

			String Exception = e.getMessage();

			return Exception;
		}
	}

	public static String checkValidationMessage2(String ExpMessage)
			throws InterruptedException, EncryptedDocumentException, InvalidFormatException, IOException {

		getFluentWebDriverWait().until(ExpectedConditions.visibilityOf(errorMessage));
		String actErrorMessage = errorMessage.getText();
		String expErrorMessage = ExpMessage;

		try {
			getFluentWebDriverWait().until(ExpectedConditions.elementToBeClickable(errorMessageCloseBtn));
			errorMessageClose2Btn.click();

			System.out.println("ValidationMessage  Actual:123" + actErrorMessage + "456");
			System.out.println("ValidationMessage  Expted:123" + expErrorMessage + "456");

			return actErrorMessage;
		} catch (Exception ee) {

			System.out.println("ValidationMessage  :  " + actErrorMessage + " Value Expected : " + expErrorMessage);

			return actErrorMessage;
		}

	}
	
