	public boolean checkSavedVoucherInPaymentsVAT()
			throws InterruptedException, EncryptedDocumentException, InvalidFormatException, IOException {

		click(previousBtn);

		System.err.println(" click on previous page");

		String expMessage = "Voucher loaded successfully";
		String actMessage = checkValidationMessage(expMessage);

		getFluentWebDriverWait().until(ExpectedConditions.elementToBeClickable(documentNumberTxt));
		String actDocNo = documentNumberTxt.getAttribute("value");
		String expDocNo = "1";

		getFluentWebDriverWait().until(ExpectedConditions.elementToBeClickable(voucherHeaderCurrency));
		String actvoucherHeaderCurrency = voucherHeaderCurrency.getAttribute("value");
		String expvoucherHeaderCurrency = "AED";

		int count = entryPageRow1List.size();
		ArrayList<String> one = new ArrayList<>();
		for (int i = 0; i < count; i++) {
			String data = entryPageRow1List.get(i).getText();
			one.add(data);
		}

		String actentryPageRow1ListString = one.toString();
		String expentryPageRow1ListString = "[1, Vendor A, Std Rate, 100.00, PurVou:1 : " + getCurrentdateDayFormat()
				+ ", , 0.00, 0.0000, -1,302.0000]";

		System.err.println("entryPageRow1List ACT:" + actentryPageRow1ListString);
		System.err.println("entryPageRow1List Exp:" + expentryPageRow1ListString);

		System.out.println("*********** Voucher No : " + actDocNo + "  value expected  " + expDocNo);
		System.out.println("*********** Warehouse  : " + actvoucherHeaderCurrency + "  value expected  "
				+ expvoucherHeaderCurrency);

		Thread.sleep(2000);

		click(toggleBtn);
		Thread.sleep(2000);

		click(postingDetailsBtn);

		Thread.sleep(2000);

		getFluentWebDriverWait().until(ExpectedConditions.elementToBeClickable(postingDetailsDebitSum));

		String actpostingDetailsDebitList = listOfElements(postingDetailsDebitList);
		String exppostingDetailsDebitList = "[Vendor A, 1,400.00]";

		System.err.println("postingDetailsDebitList ACT : " + actpostingDetailsDebitList);
		System.err.println("postingDetailsDebitList EXP : " + exppostingDetailsDebitList);

		String actpostingDetailsCreditList = listOfElements(postingDetailsCreditList);
		String exppostingDetailsCreditList = "[Bank, 1,400.00]";

		System.err.println("postingDetailsCreditList ACT : " + actpostingDetailsCreditList);
		System.err.println("postingDetailsCreditList EXP : " + exppostingDetailsCreditList);

		String actpostingDetailsDebitSum = postingDetailsDebitSum.getText();
		String exppostingDetailsDebitSum = "1,400.00";

		System.err.println(
				"postingDetailsDebitSum : " + actpostingDetailsDebitSum + " Value Exp : " + exppostingDetailsDebitSum);

		String actpostingDetailsCreditSum = postingDetailsCreditSum.getText();
		String exppostingDetailsCreditSum = "1,400.00";

		System.err.println("postingDetailsCreditSum : " + actpostingDetailsCreditSum + " Value Exp : "
				+ exppostingDetailsCreditSum);

		Thread.sleep(2000);

		getDriver().navigate().refresh();

		Thread.sleep(2000);

		if (actDocNo.equalsIgnoreCase(expDocNo) && actvoucherHeaderCurrency.equalsIgnoreCase(expvoucherHeaderCurrency)
				&& actentryPageRow1ListString.equalsIgnoreCase(expentryPageRow1ListString) &&

				actpostingDetailsDebitList.equalsIgnoreCase(exppostingDetailsDebitList)
				&& actpostingDetailsCreditList.equalsIgnoreCase(exppostingDetailsCreditList)
				&& actpostingDetailsDebitSum.equalsIgnoreCase(exppostingDetailsDebitSum)
				&& actpostingDetailsCreditSum.equalsIgnoreCase(exppostingDetailsCreditSum)) {
			return true;
		} else {
			return false;
		}
	}

