	public boolean checEnableCurrencyAndPOstDiffernceInCreditNote()
			throws EncryptedDocumentException, InvalidFormatException, InterruptedException, IOException {

		click(financialsMenu);

		click(financialsTransactionMenu);

		click(finTransJournalsMenu);

		Thread.sleep(2000);
		click(creditNotesVoucher);

		Thread.sleep(2000);

		Thread.sleep(3500);
		click(vouHomePage_settingsBtn);

		Thread.sleep(2000);
		click(miscellaneousTabInDC);

		Thread.sleep(2000);
		click(mis_CurrencyExpBtn);

		Thread.sleep(2000);

		if (miscel_PostDiffExchangeRateChkboxIsSelected.isSelected() == false) {

			Thread.sleep(2000);
			click(miscel_PostDiffExchangeRateChkbox);
		}

		String actAlert = "";
		String expAlert = "";

		if (getIsAlertPresent()) {

			actAlert = getAlert().getText();
			expAlert = "Do you want to create a new field for Exchange Rate?";

			System.err.println(" ALert Text Dispalyed ACT:" + actAlert);
			System.err.println(" ALert Text Dispalyed EXP:" + expAlert);
			getAlert().accept();
		}

		boolean actmiscel_PostDiffExchangeRateChkbox = miscel_PostDiffExchangeRateChkboxIsSelected.isSelected();
		boolean expmiscel_PostDiffExchangeRateChkbox = true;

		System.err.println("Enable Status of miscel_PostDiffExchangeRateChkbox : "
				+ actmiscel_PostDiffExchangeRateChkbox + " exp :" + expmiscel_PostDiffExchangeRateChkbox);

		
		getAction().moveToElement(miscInputLocalExchangeRateChkbox).build().perform();
		if (miscInputLocalExchangeRateChkboxIsSelected.isSelected() == false) {

			Thread.sleep(2000);
			click(miscInputLocalExchangeRateChkbox);
		}

		if (miscInputExchangeRateChkboxIsSelected.isSelected() == false) {

			Thread.sleep(2000);
			click(miscInputExchangeRateChkbox);
		}

		Thread.sleep(2000);
		Select s1 = new Select(addCurrencyDrpdwn);
		s1.selectByValue("1");

		Thread.sleep(2000);
		ClickUsingJs(settingUpdateIcon);

		String expValidationMessage = "Data saved successfully";

		String actValidationMessage = checkValidationMessage(expValidationMessage);

		getFluentWebDriverWait().until(ExpectedConditions.elementToBeClickable(settings_closeBtn));
		settings_closeBtn.click();

		if (actmiscel_PostDiffExchangeRateChkbox == expmiscel_PostDiffExchangeRateChkbox
				&& actAlert.equalsIgnoreCase(expAlert) && actValidationMessage.equalsIgnoreCase(expValidationMessage)) {
			return true;
		} else {
			return false;

		}

	}

